rewrite-uri.template:
@{
            var parameters = context.Request.MatchedParameters;
            var modelId = parameters.ContainsKey("modelId") ? parameters["modelId"] : "";
            var resultId = parameters.ContainsKey("resultId") ? parameters["resultId"] : null;
            if (resultId != null) {
                return $"/documentintelligence/documentModels/{modelId}/analyzeResults/{resultId}?api-version=${api_version}";
            }
            return $"/documentintelligence/documentModels/{modelId}:analyze?api-version=${api_version}";
        }

when.condition:
@{
                if (context.Response.StatusCode != 200) { return false; }
                var body = context.Response.Body?.As<JObject>(preserveContent: true);
                return body != null && (string)body["status"] == "succeeded" && body["analyzeResult"] != null;
            }

set-variable.value:
@{
                    var backendLocation = context.Response.Headers.GetValueOrDefault("Operation-Location", "");
                    var marker = "/documentModels/";
                    var tailStart = backendLocation.IndexOf(marker);
                    var originalPath = context.Request.OriginalUrl.Path;
                    var baseEnd = originalPath.IndexOf(marker);
                    if (tailStart < 0 || baseEnd < 0) {
                        return "";
                    }
                    var tail = backendLocation.Substring(tailStart + marker.Length);
                    var queryStart = tail.IndexOf('?');
                    if (queryStart >= 0) {
                        tail = tail.Substring(0, queryStart);
                    }
                    var basePath = originalPath.Substring(0, baseEnd);
                    return $"{context.Request.OriginalUrl.Scheme}://{context.Request.OriginalUrl.Host}{basePath}{marker}{tail}";
                }
